('bmlt-advanced-urine-sediment-morphology-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',4000,$json${"question":"Which urinary cast is most strongly associated with glomerular bleeding?","translation":"","options":["Red blood cell cast","Hyaline cast","Waxy cast","Fatty cast"],"correctIndex":0,"explanation":"Red blood cell casts strongly suggest bleeding originating within the nephron, commonly glomerular disease.","explanationNe":"RBC cast ले nephron भित्र, प्रायः glomerulus बाट भएको bleeding जनाउँछ।","topic":"Urinary casts"}$json$::jsonb,true),
