('bmlt-advanced-urine-sediment-morphology-mock-020','BMLT','BMLT NHPC Licensing','mock','free',4119,$json${"question":"A technologist sees a cylindrical structure with parallel sides and a rounded end. It contains red cells. What is it?","translation":"","options":["Red blood cell cast","Mucus thread","Squamous epithelial cell","Calcium oxalate crystal"],"correctIndex":0,"explanation":"A cylindrical matrix containing RBCs is an RBC cast.","explanationNe":"Cylindrical matrix भित्र RBC भए RBC cast भनिन्छ।","topic":"Cast morphology"}$json$::jsonb,true),
('bmlt-advanced-urine-sediment-morphology-mock-021','BMLT','BMLT NHPC Licensing','mock','free',4120,$json${"question":"A urine sediment has numerous bacteria but no pyuria. What should the report interpretation consider?","translation":"","options":["Contamination or asymptomatic bacteriuria as well as clinical context","Definite symptomatic UTI in every patient","Renal failure only","A positive culture without testing"],"correctIndex":0,"explanation":"Bacteriuria without pyuria needs careful interpretation, including symptoms, collection quality and culture when indicated.","explanationNe":"Pyuria नभएको bacteriuria लाई symptoms, specimen quality र आवश्यक culture सँग मिलाएर हेर्नुपर्छ।","topic":"Bacteriuria"}$json$::jsonb,true),
('bmlt-advanced-urine-sediment-morphology-mock-022','BMLT','BMLT NHPC Licensing','mock','free',4121,$json${"question":"A fresh specimen is needed for accurate sediment morphology. Which handling is most appropriate?","translation":"","options":["Examine promptly or refrigerate if delay is unavoidable, following protocol","Leave open at room temperature overnight","Add formalin to every routine urine sample","Expose it to direct sunlight"],"correctIndex":0,"explanation":"Prompt analysis is preferred; validated refrigeration can limit changes when a delay occurs.","explanationNe":"छिटो जाँच उत्तम हुन्छ; ढिलाइ भए protocol अनुसार refrigerate गर्न सकिन्छ।","topic":"Specimen handling"}$json$::jsonb,true),
('bmlt-advanced-urine-sediment-morphology-mock-023','BMLT','BMLT NHPC Licensing','mock','free',4122,$json${"question":"A report notes many mucus threads but no casts. Which statement is most accurate?","translation":"","options":["Mucus threads are not equivalent to urinary casts","Mucus threads prove glomerular disease","Mucus threads are always RBC casts","Mucus threads confirm UTI"],"correctIndex":0,"explanation":"Mucus is irregular and lacks the defined cylindrical matrix of a true cast.","explanationNe":"Mucus thread मा true cast जस्तो स्पष्ट cylindrical matrix हुँदैन।","topic":"Cast differentiation"}$json$::jsonb,true),
('bmlt-advanced-urine-sediment-morphology-mock-024','BMLT','BMLT NHPC Licensing','mock','free',4123,$json${"question":"A urine sediment shows a cast containing renal tubular epithelial cells. What does this most directly indicate?","translation":"","options":["Cells have been incorporated into a cast within renal tubules","The sample was definitely contaminated externally","The patient has a bladder-only disorder","The finding is a type of crystal"],"correctIndex":0,"explanation":"Cellular casts form in renal tubules and indicate intrarenal processes.","explanationNe":"Cellular cast renal tubule भित्र बन्ने भएकाले intrarenal प्रक्रिया जनाउँछ।","topic":"Cellular casts"}$json$::jsonb,true),
('bmlt-advanced-urine-sediment-morphology-mock-025','BMLT','BMLT NHPC Licensing','mock','free',4124,$json${"question":"A urine microscopy result conflicts with the dipstick and clinical picture. What should the technologist do?","translation":"","options":["Review specimen quality, repeat as appropriate and communicate discrepancies","Alter the microscopy result to match dipstick","Ignore the clinician's concern","Release an unsupported diagnosis"],"correctIndex":0,"explanation":"Discordant results require review of sample integrity, method limitations and repeat testing when indicated.","explanationNe":"नमिल्ने result आए specimen quality र method जाँचेर आवश्यक भए repeat तथा communication गर्नुपर्छ।","topic":"Result validation"}$json$::jsonb,true)
